#include "collaborationtools.hpp"
#include "language.hpp"
#include <QFormLayout>
#include <QVBoxLayout>
#include <QHBoxLayout>
#include <QLineEdit>
#include <QSpinBox>
#include <QLabel>
#include <QPushButton>
#include <QNetworkInterface>
namespace {QString text(const char* de,const char* en){return Language::text(QString::fromUtf8(Language::current()=="de"?de:en));}}
CollaborationTools::CollaborationTools(LocalCollaboration* session,QWidget* parent):QWidget(parent),session_(session){
    setObjectName("localCollaboration");auto* layout=new QVBoxLayout(this);auto* description=new QLabel(text("Gemeinsam im lokalen Netzwerk. Nur ausdrücklich gestartete Sitzungen; kein Konto. Die LAN-Verbindung ist unverschlüsselt. Bibliotheken installiert jeder Teilnehmer lokal.","Work together on your local network. Sessions start explicitly; no account. LAN transport is unencrypted. Each participant installs libraries locally."));description->setWordWrap(true);layout->addWidget(description);
    auto* form=new QFormLayout;layout->addLayout(form);address_=new QLineEdit;address_->setObjectName("collaborationAddress");address_->setPlaceholderText("192.168.1.10");form->addRow(text("Adresse des Hosts","Host address"),address_);port_=new QSpinBox;port_->setObjectName("collaborationPort");port_->setRange(1,65535);port_->setValue(42626);form->addRow(text("Port zum Beitreten","Join port"),port_);ticket_=new QLineEdit;ticket_->setObjectName("collaborationTicket");ticket_->setMaxLength(64);form->addRow(text("Sitzungsticket","Session ticket"),ticket_);
    auto* row=new QHBoxLayout;layout->addLayout(row);auto* host=new QPushButton(text("Hosten","Host"));host->setObjectName("collaborationHost");row->addWidget(host);connect(host,&QPushButton::clicked,this,&CollaborationTools::hostRequested);auto* join=new QPushButton(text("Beitreten","Join"));join->setObjectName("collaborationJoin");row->addWidget(join);connect(join,&QPushButton::clicked,this,[this]{emit joinRequested(address_->text().trimmed(),quint16(port_->value()),ticket_->text().trimmed());});auto* leave=new QPushButton(text("Trennen","Disconnect"));leave->setObjectName("collaborationDisconnect");row->addWidget(leave);connect(leave,&QPushButton::clicked,session_,&LocalCollaboration::stop);
    status_=new QLabel;status_->setObjectName("collaborationStatus");status_->setWordWrap(true);status_->setTextInteractionFlags(Qt::TextSelectableByMouse);layout->addWidget(status_);conflicts_=new QLabel;conflicts_->setWordWrap(true);conflicts_->setTextFormat(Qt::PlainText);layout->addWidget(conflicts_);auto* resolve=new QHBoxLayout;layout->addLayout(resolve);accept_=new QPushButton(text("Host-Stand übernehmen","Accept host version"));accept_->setObjectName("collaborationAcceptRemote");keep_=new QPushButton(text("Eigene Konflikte übernehmen","Apply my conflicting changes"));keep_->setObjectName("collaborationKeepLocal");compare_=new QPushButton(text("Entwürfe vergleichen","Compare drafts"));resolve->addWidget(compare_);resolve->addWidget(accept_);resolve->addWidget(keep_);connect(accept_,&QPushButton::clicked,this,&CollaborationTools::acceptRemoteRequested);connect(keep_,&QPushButton::clicked,this,&CollaborationTools::keepLocalRequested);connect(compare_,&QPushButton::clicked,this,&CollaborationTools::compareRequested);clearConflict();layout->addStretch();connect(session_,&LocalCollaboration::connectionChanged,this,&CollaborationTools::refresh);refresh();
}
void CollaborationTools::refresh(){if(session_->hosting()){QStringList addresses;for(const auto& address:QNetworkInterface::allAddresses())if(address.protocol()==QAbstractSocket::IPv4Protocol&&!address.isLoopback())addresses.append(address.toString());status_->setText(text("Host aktiv · ","Hosting · ")+addresses.join(", ")+":"+QString::number(session_->port())+" · "+QString::number(session_->peerCount())+text(" Teilnehmer"," peers"));ticket_->setText(session_->ticket());port_->setValue(session_->port());}else status_->setText(session_->connected()?text("Verbunden · Änderungen werden lokal synchronisiert","Connected · synchronizing local changes"):text("Keine Sitzung aktiv","No active session"));}
void CollaborationTools::showConflict(const QStringList& paths){conflicts_->setText(text("Konflikt: Lokaler Entwurf bleibt erhalten. Wähle die Auflösung.\n","Conflict: your local draft is preserved. Choose a resolution.\n")+paths.join('\n'));conflicts_->show();accept_->show();keep_->show();compare_->show();}
void CollaborationTools::clearConflict(){conflicts_->hide();accept_->hide();keep_->hide();compare_->hide();}
